import Foundation
import AVFoundation
import VideoToolbox
func emit(_ progress:Int,_ text:String){let d=try! JSONSerialization.data(withJSONObject:["progress":progress,"text":text]);FileHandle.standardOutput.write(d);FileHandle.standardOutput.write(Data([10]))}
func failure(_ text:String)->NSError{NSError(domain:"LightVid",code:1,userInfo:[NSLocalizedDescriptionKey:text])}
@available(macOS 26.0,*) func supported(_ w:Int,_ h:Int)->Bool {VTLowLatencySuperResolutionScalerConfiguration.isSupported && VTLowLatencySuperResolutionScalerConfiguration.supportedScaleFactors(frameWidth:w,frameHeight:h).contains(2)}
@available(macOS 26.0,*) func enhance(_ source:URL,_ destination:URL) async throws {
 let asset=AVURLAsset(url:source);guard let track=try await asset.loadTracks(withMediaType:.video).first else{throw failure("没有可处理的视频轨")};let descriptions=try await track.load(.formatDescriptions);guard let format=descriptions.first else{throw failure("无法读取视频格式")};let dim=CMVideoFormatDescriptionGetDimensions(format),w=Int(dim.width),h=Int(dim.height)
 guard supported(w,h) else{throw failure("当前设备或视频尺寸不支持 Apple AI 2×增强，请选择自然增强")}
 if let ext=CMFormatDescriptionGetExtensions(format) as? [String:Any],let transfer=ext[kCMFormatDescriptionExtension_TransferFunction as String] as? String,transfer.contains("2084")||transfer.contains("HLG"){throw failure("当前 AI 增强仅支持 SDR 视频，请先转换 HDR 素材")}
 let duration=try await asset.load(.duration),fps=try await track.load(.nominalFrameRate),transform=try await track.load(.preferredTransform),range=try await track.load(.timeRange)
 let configuration=VTLowLatencySuperResolutionScalerConfiguration(frameWidth:w,frameHeight:h,scaleFactor:2),processor=VTFrameProcessor();emit(1,"正在加载 Apple 原生 AI 超分辨率引擎…");try processor.startSession(configuration:configuration);defer{processor.endSession()}
 let reader=try AVAssetReader(asset:asset);var sourceAttributes=configuration.sourcePixelBufferAttributes;sourceAttributes[kCVPixelBufferIOSurfacePropertiesKey as String]=[:];let read=AVAssetReaderTrackOutput(track:track,outputSettings:sourceAttributes);read.alwaysCopiesSampleData=false;guard reader.canAdd(read) else{throw failure("无法建立 AI 视频读取器")};reader.add(read)
 let writer=try AVAssetWriter(outputURL:destination,fileType:.mp4);var settings:[String:Any]=[AVVideoCodecKey:AVVideoCodecType.h264,AVVideoWidthKey:w*2,AVVideoHeightKey:h*2,AVVideoCompressionPropertiesKey:[AVVideoAverageBitRateKey:max(4_000_000,Int(Double(w*h*4)*Double(max(1,fps))*0.16)),AVVideoProfileLevelKey:AVVideoProfileLevelH264HighAutoLevel,AVVideoExpectedSourceFrameRateKey:Int(max(1,fps)),AVVideoAllowFrameReorderingKey:false]];if let aspect=CMFormatDescriptionGetExtension(format,extensionKey:kCMFormatDescriptionExtension_PixelAspectRatio) as? [String:Any],let horizontal=aspect[kCMFormatDescriptionKey_PixelAspectRatioHorizontalSpacing as String],let vertical=aspect[kCMFormatDescriptionKey_PixelAspectRatioVerticalSpacing as String]{settings[AVVideoPixelAspectRatioKey]=[AVVideoPixelAspectRatioHorizontalSpacingKey:horizontal,AVVideoPixelAspectRatioVerticalSpacingKey:vertical]};let input=AVAssetWriterInput(mediaType:.video,outputSettings:settings);input.expectsMediaDataInRealTime=false;input.transform=CGAffineTransform(a:transform.a,b:transform.b,c:transform.c,d:transform.d,tx:transform.tx*2,ty:transform.ty*2);guard writer.canAdd(input) else{throw failure("无法建立 AI 视频编码器")};writer.add(input)
 var attrs=configuration.destinationPixelBufferAttributes;attrs[kCVPixelBufferWidthKey as String]=w*2;attrs[kCVPixelBufferHeightKey as String]=h*2;attrs[kCVPixelBufferIOSurfacePropertiesKey as String]=[:];var pool:CVPixelBufferPool?;guard CVPixelBufferPoolCreate(kCFAllocatorDefault,nil,attrs as CFDictionary,&pool)==kCVReturnSuccess,let pool else{throw failure("无法分配 AI 视频缓冲区")}
 guard reader.startReading(),writer.startWriting() else{throw reader.error ?? writer.error ?? failure("无法启动视频处理")};writer.startSession(atSourceTime:.zero);var n=0
 do {while let sample=read.copyNextSampleBuffer(){try Task.checkCancellation();guard let source=CMSampleBufferGetImageBuffer(sample) else{throw failure("视频帧读取失败")};let pts=CMSampleBufferGetPresentationTimeStamp(sample);if CMTimeCompare(pts,CMTimeRangeGetEnd(range))>=0{continue};var output:CVPixelBuffer?;guard CVPixelBufferPoolCreatePixelBuffer(kCFAllocatorDefault,pool,&output)==kCVReturnSuccess,let output,let a=VTFrameProcessorFrame(buffer:source,presentationTimeStamp:pts),let b=VTFrameProcessorFrame(buffer:output,presentationTimeStamp:pts) else{throw failure("AI 帧缓冲区不可用")};CVBufferPropagateAttachments(source,output);let params=VTLowLatencySuperResolutionScalerParameters(sourceFrame:a,destinationFrame:b);_ = try await processor.process(parameters:params);while !input.isReadyForMoreMediaData {if writer.status == .failed{throw writer.error ?? failure("视频编码失败")};try await Task.sleep(nanoseconds:1_000_000)};var desc:CMVideoFormatDescription?;guard CMVideoFormatDescriptionCreateForImageBuffer(allocator:kCFAllocatorDefault,imageBuffer:output,formatDescriptionOut:&desc)==noErr,let desc else{throw failure("无法建立增强帧格式")};var timing=CMSampleTimingInfo(duration:CMSampleBufferGetDuration(sample),presentationTimeStamp:pts,decodeTimeStamp:.invalid);var ready:CMSampleBuffer?;guard CMSampleBufferCreateReadyWithImageBuffer(allocator:kCFAllocatorDefault,imageBuffer:output,formatDescription:desc,sampleTiming:&timing,sampleBufferOut:&ready)==noErr,let ready,input.append(ready) else{throw writer.error ?? failure("无法写入增强视频")};n+=1;if n%15==0{emit(min(98,max(2,Int(pts.seconds/max(0.001,duration.seconds)*98))),"AI 高清增强 · 已处理 \(n) 帧")}}
 guard reader.status == .completed,n>0 else{throw reader.error ?? failure("视频未完整读取")};writer.endSession(atSourceTime:CMTimeRangeGetEnd(range));input.markAsFinished();await writer.finishWriting();guard writer.status == .completed else{throw writer.error ?? failure("视频未完整写入")};emit(100,"AI 2×增强完成 · \(w*2)×\(h*2) · \(n) 帧")
 }catch{reader.cancelReading();writer.cancelWriting();throw error}
}
@main struct Main {static func main() async {do{let args=CommandLine.arguments;if args.count==4&&args[1]=="--probe" {let w=Int(args[2]) ?? 0,h=Int(args[3]) ?? 0;let ok:Bool;if #available(macOS 26.0,*){ok=supported(w,h)}else{ok=false};print(ok ? "supported":"unsupported");return};guard args.count==3 else{throw failure("缺少输入或输出路径")};if #available(macOS 26.0,*){try await enhance(URL(fileURLWithPath:args[1]),URL(fileURLWithPath:args[2]))}else{throw failure("Apple AI 高清增强需要 macOS 26 及支持的设备，请选择自然增强")}}catch{FileHandle.standardError.write(Data((error.localizedDescription+"\n").utf8));exit(1)}}}
